  for (int i = 0; i < 40; i++) start_step_and_stop_gl_hack(morph3d, "Morph3D");
  const size_t after = __sanitizer_get_current_allocated_bytes();
  TEST_ASSERT_TRUE_MESSAGE(after < before + 64 * 1024, "allocated bytes grew");
}

