   c->x += c->dx * MOVE_MULT;
   c->y += c->dy * MOVE_MULT;
   if (c->x > ci->XMAX/2 || c->x < 0 - ci->XMAX/2 ||
       c->y > ci->YMAX/2 || c->y < 0 - ci->YMAX/2) {
